    protected function doSave(PropelPDO $con)
    {
        $affectedRows = 0; // initialize var to track total num of affected rows
        if (!$this->alreadyInSave) {
            $this->alreadyInSave = true;

            // We call the save method on the following object(s) if they
            // were passed to this object by their corresponding set
            // method.  This object relates to these object(s) by a
            // foreign key reference.

            if ($this->aUnidadDocumental !== null) {
                if ($this->aUnidadDocumental->isModified() || $this->aUnidadDocumental->isNew()) {
                    $affectedRows += $this->aUnidadDocumental->save($con);
                }
                $this->setUnidadDocumental($this->aUnidadDocumental);
            }

            if ($this->aNivelDescripcion !== null) {
                if ($this->aNivelDescripcion->isModified() || $this->aNivelDescripcion->isNew()) {
                    $affectedRows += $this->aNivelDescripcion->save($con);
                }
                $this->setNivelDescripcion($this->aNivelDescripcion);
