    protected function doInsert(PropelPDO $con)
    {
        $this->modifiedColumns[] = IsadPeer::ISAD_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(IsadPeer::ISAD_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key (' . IsadPeer::ISAD_ID . ')');
        }
        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(IsadPeer::ISAD_ID);
        $pk = BasePeer::doInsert($criteria, $con);
        $this->setIsadId($pk);  //[IMV] update autoincrement primary key
        $this->setNew(false);
    }

