     * @param array $columns Array of column names to validate.
     * @return mixed <code>true</code> if all validations pass; array of <code>ValidationFailed</code> objects otherwise.
     */
    protected function doValidate($columns = null)
    {
        if (!$this->alreadyInValidation) {
            $this->alreadyInValidation = true;
            $retval = null;

            $failureMap = array();


            // We call the validate method on the following object(s) if they
            // were passed to this object by their corresponding set
            // method.  This object relates to these object(s) by a
            // foreign key reference.

            if ($this->aUnidadDocumental !== null) {
                if (!$this->aUnidadDocumental->validate($columns)) {
                    $failureMap = array_merge($failureMap, $this->aUnidadDocumental->getValidationFailures());
                }
            }

            if ($this->aNivelDescripcion !== null) {
                if (!$this->aNivelDescripcion->validate($columns)) {
                    $failureMap = array_merge($failureMap, $this->aNivelDescripcion->getValidationFailures());
